fn getdomain(x: Vec<i8>) -> Vec<i8> {
    // We assume `x` is non-empty as per the problem statement.
    let mut min_val = x[0];
    let mut max_val = x[0];

    for &v in &x {
        if v < min_val {
            min_val = v;
        }
        if v > max_val {
            max_val = v;
        }
    }

    vec![min_val, max_val]
}

fn main() {
    let data = vec![3, -1, 7, 0, 5];
    let domain = getdomain(data);
    println!("Domain: {:?}", domain); // Should print `Domain: [-1, 7]`
}